import { Component } from '@angular/core';

@Component({
    selector: 'app-transaction-start',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-start.component.html',
    styleUrls: ['./transaction-start.component.css']
})
export class TransactionStartComponent {
    showButtonChoseIsIncome = false;
	firstLoad = true;

	constructor() { }

	ngOnInit() {
		this.firstLoad = false;
	}

    CreateTransaction() {
		this.showButtonChoseIsIncome = !this.showButtonChoseIsIncome;
    }

}
<div class="mainChild">
    <div class="list-container">
        <app-transaction-list></app-transaction-list>
    </div>
</div>

<button
    class="default-button bottom-button invert-button"
    ngClass="{{ showButtonChoseIsIncome ? 'active' : '' }}"
>
    <div
        class="button-create"
        ngClass="{{ showButtonChoseIsIncome ? 'active' : !firstLoad ? 'off' : '' }}"
        (click)="CreateTransaction()"
    >
        <div class="button-create-text secondary">
            <span *ngIf="!showButtonChoseIsIncome">Create Transaction</span>
            <span *ngIf="showButtonChoseIsIncome">X</span>
        </div>
    </div>
    <div class="income-expense-container">
        <div>Income</div>
        <div>Expense</div>
    </div>
    <!-- <span class="secondary">Create Transaction</span> -->
</button>
